update public.learning_paths
set
  title = 'Diversity, Equity, and Multicultural Education',
  goal = 'Diversity, Equity, and Multicultural Education',
  summary = 'This course prepares future educators to build culturally sustaining, inclusive, and equity-centered classrooms. Students examine identity, culture, race, language, gender, sexuality, religion, disability, socioeconomic inequality, anti-bias education, family and community partnership, curriculum representation, classroom climate, civil-rights obligations, and systems-level equity data. The course emphasizes rigorous instruction, belonging, critical reflection, professional responsibility, and practical strategies for teaching across diverse cultural contexts.',
  data = $demejson${"slug": "diversity-equity-and-multicultural-education", "title": "Diversity, Equity, and Multicultural Education", "description": "This course prepares future educators to build culturally sustaining, inclusive, and equity-centered classrooms. Students examine identity, culture, race, language, gender, sexuality, religion, disability, socioeconomic inequality, anti-bias education, family and community partnership, curriculum representation, classroom climate, civil-rights obligations, and systems-level equity data. The course emphasizes rigorous instruction, belonging, critical reflection, professional responsibility, and practical strategies for teaching across diverse cultural contexts.", "topics": [{"id": "e8ff9c55-9a4e-430a-b178-b21a34c860f2", "type": "topic", "title": "Foundations of Multicultural and Equity-Centered Education", "description": "This opening unit gives students a shared language for multicultural education and equity-centered teaching. It frames diversity as a strength, equity as a design obligation, and belonging as a condition for rigorous learning.", "children": [{"id": "db14f0b5-5420-4bf1-873c-c43bc225bf81", "type": "subtopic", "title": "Multicultural education frameworks", "children": [{"id": "8c172948-73d7-4a71-acd6-03c740751971", "type": "concept", "title": "Contributions, additive, transformative, and social-action approaches"}, {"id": "848ce892-72d9-4845-b542-2c03d6ed3a72", "type": "concept", "title": "Multicultural, intercultural, anti-bias, and anti-oppressive education"}, {"id": "c60f5415-acd6-40c7-8b3d-47a05d7f3c3b", "type": "concept", "title": "Identity, diversity, justice, and action domains"}], "description": "Students learn the major purposes and traditions of multicultural education, from representation to structural change."}, {"id": "7caf7e3d-26bb-49d9-bffc-c73a17483698", "type": "subtopic", "title": "Equity, inclusion, and belonging", "children": [{"id": "30a66656-d8d1-4dbf-92a1-edfb1d48e1a3", "type": "concept", "title": "Equality versus equity"}, {"id": "9c3a91aa-b5d2-4cbe-b1dd-5499c874d849", "type": "concept", "title": "Inclusion versus assimilation"}, {"id": "e5545588-c93c-4e71-9510-10597979840e", "type": "concept", "title": "Belonging, dignity, and psychological safety"}], "description": "Students distinguish common terms that are often used interchangeably but imply different actions."}, {"id": "9d331c78-00ec-42fc-a8e2-ef1170757cd7", "type": "subtopic", "title": "Historical and social context", "children": [{"id": "dac681b9-834a-40b2-98d2-77f4cbcbb6a7", "type": "concept", "title": "Segregation and desegregation"}, {"id": "3daee968-adf7-4d47-bd9c-baa97678f7f8", "type": "concept", "title": "Language, immigration, and schooling"}, {"id": "682441b1-1970-4bfe-b3a6-374a03d71357", "type": "concept", "title": "Disability rights and gender equity in education"}], "description": "Students connect classroom practice to broader histories of schooling, exclusion, and reform."}]}, {"id": "4d388436-25be-454f-b1d6-b62e61e12b58", "type": "topic", "title": "Identity, Culture, and Teacher Self-Reflection", "description": "Equity-centered teaching begins with self-knowledge. Students examine how identity, culture, experience, and power shape what educators notice, value, expect, and normalize.", "children": [{"id": "5bae8446-2622-434b-be53-9bd486d4e0e1", "type": "subtopic", "title": "Identity and positionality", "children": [{"id": "2695dc4b-3011-45c3-9c52-be72d0ce4218", "type": "concept", "title": "Race, ethnicity, class, gender, sexuality, language, religion, disability, and nationality"}, {"id": "3c8fe6e5-c93c-4e53-9e9f-0d4bae461aed", "type": "concept", "title": "Intersectional identity"}, {"id": "ca460130-cb8f-4f11-ba23-0a1e93a0e49f", "type": "concept", "title": "Positionality statements and reflective boundaries"}], "description": "Students learn to reflect on their own identities without making the work self-centered."}, {"id": "4c08255d-18e5-472c-9e27-5a96ca5f9d6a", "type": "subtopic", "title": "Cultural humility", "children": [{"id": "07622a89-b374-4eae-8ad4-812e1849afa3", "type": "concept", "title": "Lifelong learning and critical self-reflection"}, {"id": "adb2ac52-408a-4132-8c99-c622454ce264", "type": "concept", "title": "Power imbalance and institutional accountability"}, {"id": "2a7dfc18-c33a-4c5a-9f3e-360a2ff6c79c", "type": "concept", "title": "Repair, apology, and growth-oriented practice"}], "description": "Students distinguish humility from a checklist approach to culture."}, {"id": "5e537226-c7d9-4ee0-8e70-dd2fb5c97bd5", "type": "subtopic", "title": "Implicit bias and privilege", "children": [{"id": "dfc07caf-eb09-4acc-af0a-2ba976e0f077", "type": "concept", "title": "Implicit associations and expectation effects"}, {"id": "807a311c-34b6-452c-a221-05c7b95f8d58", "type": "concept", "title": "Privilege, normalization, and invisibility"}, {"id": "3e436ad7-24e9-4894-94d6-c32dd5a4d9e1", "type": "concept", "title": "Bias interruption routines"}], "description": "Students study bias as a professional responsibility and a design problem, not just an individual flaw."}]}, {"id": "e2c1e1ca-e4ac-4363-b4bc-8d2aaa7c4f6c", "type": "topic", "title": "Race, Ethnicity, Language, and Schooling", "description": "This unit examines how race, ethnicity, and language shape educational opportunity, identity, curriculum, discipline, placement, and achievement. Students learn to move from awareness to anti-racist and linguistically sustaining practice.", "children": [{"id": "c11aaaeb-4bd5-4842-bb94-adc97ee73a04", "type": "subtopic", "title": "Race and racism in education", "children": [{"id": "de683371-1d2d-451b-9747-be5ce4078a77", "type": "concept", "title": "Racialization and schooling history"}, {"id": "4679f030-d451-46dc-a27d-3591f0eed65d", "type": "concept", "title": "Disproportionality in discipline and special education"}, {"id": "7256f685-5b83-48ee-9d66-75f45ca09899", "type": "concept", "title": "Anti-racist classroom and school routines"}], "description": "Students analyze racism as interpersonal, institutional, historical, and curricular."}, {"id": "18878e82-e90f-4d87-8f93-e40de35e51e0", "type": "subtopic", "title": "Ethnicity, immigration, and belonging", "children": [{"id": "2d3684b0-9e58-42f8-a464-c0ae5c904d23", "type": "concept", "title": "Immigrant and refugee experiences"}, {"id": "a9854c94-673c-49db-9b3a-c3e975048fcd", "type": "concept", "title": "Ethnic identity development"}, {"id": "8c214c58-e645-4d5b-9898-af353768704c", "type": "concept", "title": "Avoiding tokenism and cultural essentialism"}], "description": "Students learn to support students whose cultural identities, migration histories, and family experiences shape school life."}, {"id": "29871ad3-42ed-4b91-8dba-bbf65f6f0931", "type": "subtopic", "title": "Language and multilingual learners", "children": [{"id": "6826737b-78f4-4c2d-be57-7046d9d19ef6", "type": "concept", "title": "Translanguaging and home-language assets"}, {"id": "4f585283-9b54-4b4e-8676-8a27d2ca48d2", "type": "concept", "title": "English learner identification and support"}, {"id": "2285e121-cea0-41ff-9a00-c84ba54983ac", "type": "concept", "title": "Language access for families"}], "description": "Students study language as an asset and a civil-rights issue."}]}, {"id": "b3bbf421-7aeb-4cdf-b074-0c76f6609257", "type": "topic", "title": "Gender, Sexuality, Religion, and Safe Learning Environments", "description": "Students need classrooms where identity is not a liability. This unit prepares educators to create respectful environments across gender, sexuality, and religion while navigating professional, legal, and community contexts.", "children": [{"id": "63cafa3c-ce59-4c3e-8d7b-6fc113fc450b", "type": "subtopic", "title": "Gender and schooling", "children": [{"id": "49ca4e0b-93d7-42e4-acf4-c5670fcf8d7d", "type": "concept", "title": "Gender stereotypes and hidden curriculum"}, {"id": "9569dd7a-6061-4452-b0b0-7262790534f6", "type": "concept", "title": "Gender-expansive students"}, {"id": "c994d810-52f1-4245-bb9b-9f4e3e7dd9dc", "type": "concept", "title": "Equitable participation and feedback patterns"}], "description": "Students examine how gender norms shape participation, expectations, curriculum, and belonging."}, {"id": "c173bcb6-3f93-47e0-a3ac-1ea869f310c6", "type": "subtopic", "title": "LGBTQ+ inclusive education", "children": [{"id": "6691c7b4-91d6-4d6d-af1f-112a638800da", "type": "concept", "title": "Names, pronouns, and privacy"}, {"id": "60b4a090-e149-42c8-b5bd-8c8093eb4775", "type": "concept", "title": "Inclusive texts and examples"}, {"id": "967be508-6433-4c1e-ad2d-1fbd30222c3b", "type": "concept", "title": "Anti-bullying and harassment response"}], "description": "Students learn classroom practices that support safety, dignity, and accurate representation."}, {"id": "074c9bd7-5dc9-4bcd-99f4-720c16ff5a84", "type": "subtopic", "title": "Religion and worldview diversity", "children": [{"id": "dce4842f-6cb6-4e4a-96a3-99e653f9ab58", "type": "concept", "title": "Religious literacy and constitutional boundaries"}, {"id": "5c2bef29-8117-444a-847c-89e0729cfcea", "type": "concept", "title": "Holidays, dress, diet, and observance"}, {"id": "213f051a-630e-462a-b5a1-508845d1e9a4", "type": "concept", "title": "Dialogue across difference"}], "description": "Students learn to address religion respectfully in public-school contexts."}]}, {"id": "fde6dd5b-234b-4cac-9368-f3c8dc58e31e", "type": "topic", "title": "Socioeconomic Inequality, Opportunity Gaps, and Community Context", "description": "This unit helps students interpret achievement differences as opportunity differences shaped by resources, policies, neighborhoods, and institutional design rather than student deficits.", "children": [{"id": "083e24b4-d623-4222-8111-08515e276fca", "type": "subtopic", "title": "Class and educational opportunity", "children": [{"id": "f6a903dd-e18f-47d6-aa51-c7b5acf73b69", "type": "concept", "title": "Poverty, housing, food security, and attendance"}, {"id": "4cc2cb36-a129-40e1-9d29-68bc489717fa", "type": "concept", "title": "School funding and resource access"}, {"id": "978e5069-8ef6-48d3-bb0f-7a6dff46fb20", "type": "concept", "title": "Digital divide and enrichment opportunity"}], "description": "Students connect socioeconomic conditions to school experience without stereotyping families."}, {"id": "66cfdb42-3f1f-43f7-8193-e20d7dce2c71", "type": "subtopic", "title": "Opportunity gaps and institutional barriers", "children": [{"id": "3be5e371-ffec-4e90-bde9-d033ea966ffb", "type": "concept", "title": "Tracking and advanced-course access"}, {"id": "5a267cec-85b2-4ad7-bb67-01fee6bb5335", "type": "concept", "title": "Discipline, attendance, and exclusion"}, {"id": "2151449b-ce42-45db-abef-edf9b9f48694", "type": "concept", "title": "Administrative burden and access barriers"}], "description": "Students learn to analyze barriers embedded in systems and routines."}, {"id": "f50cf42f-7d4e-4497-b4b0-264434b5e1af", "type": "subtopic", "title": "Funds of knowledge and community assets", "children": [{"id": "1fd71521-8e69-429c-b20b-139a460261fb", "type": "concept", "title": "Family expertise and cultural wealth"}, {"id": "f393e8b0-d8c9-47fc-a134-263f36e3d43c", "type": "concept", "title": "Community mapping"}, {"id": "f1e55fff-bad5-443a-a251-f41d860f8933", "type": "concept", "title": "Asset-based versus deficit narratives"}], "description": "Students learn to build curriculum and relationships from community strengths."}]}, {"id": "a54200b4-65cd-4009-bbeb-5f2e896b2893", "type": "topic", "title": "Disability Justice, Universal Design, and Inclusive Pedagogy", "description": "Inclusive education is not an add-on after a lesson is built. This unit teaches students to anticipate learner variability, reduce barriers, and collaborate around access, participation, and high expectations.", "children": [{"id": "251a6383-2fbc-4398-9d79-dfa7c43e53be", "type": "subtopic", "title": "Disability and ableism", "children": [{"id": "032c443c-0f37-4c31-a043-515b95e1a461", "type": "concept", "title": "Medical, social, and justice models of disability"}, {"id": "ebf58dc6-1d65-4b65-8326-acd7320f6a1b", "type": "concept", "title": "Ableism and deficit assumptions"}, {"id": "8621a49b-0c7f-40c6-8efc-f0945e09a63e", "type": "concept", "title": "Disability culture and student agency"}], "description": "Students learn to understand disability through rights, identity, access, and design."}, {"id": "148deb3a-cd6a-473c-b336-0023a8ba7514", "type": "subtopic", "title": "Universal Design for Learning", "children": [{"id": "00eced8d-9745-416c-827a-860469e746da", "type": "concept", "title": "Multiple means of engagement"}, {"id": "d3e1dc44-645d-4679-910a-1cd1002116dc", "type": "concept", "title": "Multiple means of representation"}, {"id": "9be9b0fe-500a-4ba6-a841-dcf6eb4f6851", "type": "concept", "title": "Multiple means of action and expression"}], "description": "Students apply UDL as proactive design rather than individual remediation."}, {"id": "68cf2493-ed88-4b80-837d-fcba641f3702", "type": "subtopic", "title": "Accommodations and collaboration", "children": [{"id": "d82afd79-42e4-40dc-8c1b-147b3361406f", "type": "concept", "title": "IEP and 504 basics"}, {"id": "58bb6875-acfb-4ece-a92a-88732f76b7b9", "type": "concept", "title": "Assistive technology and accessible materials"}, {"id": "300bbb8d-6264-439a-bf51-884504157e75", "type": "concept", "title": "Co-teaching, families, and related-service collaboration"}], "description": "Students learn how legal plans and team practice support access."}]}, {"id": "d1cd0be3-8f6e-4759-8aa4-e4f60172da1d", "type": "topic", "title": "Culturally Relevant, Responsive, and Sustaining Pedagogy", "description": "This unit turns equity commitments into instructional practice. Students learn to design rigorous learning that connects to students' identities, communities, histories, languages, and intellectual strengths.", "children": [{"id": "ab1b0a36-3b57-4262-89f5-ec20cd6ed5ee", "type": "subtopic", "title": "Culturally relevant pedagogy", "children": [{"id": "2fc20b3f-3248-41ab-961d-49b8492ba31a", "type": "concept", "title": "Ladson-Billings framework"}, {"id": "d413f866-86fd-4f92-8b44-a3865d7d05ec", "type": "concept", "title": "High expectations and intellectual rigor"}, {"id": "33d49906-b898-4d9b-b261-73e2f14a7099", "type": "concept", "title": "Critical consciousness and real-world relevance"}], "description": "Students study teaching that supports academic success, cultural competence, and critical consciousness."}, {"id": "475f516b-e631-4e53-8fd9-8680d58d7ee8", "type": "subtopic", "title": "Culturally responsive teaching", "children": [{"id": "ca62fd6b-9e8b-4728-9273-0fdfa863f736", "type": "concept", "title": "Learning partnerships"}, {"id": "2ec709a2-0ed8-48d9-8b69-deecfddb3562", "type": "concept", "title": "Schema, information processing, and productive struggle"}, {"id": "f214a15a-6ed7-42d8-ae0d-5558bb8c6e13", "type": "concept", "title": "Warm demander practice"}], "description": "Students learn practices that connect culture, cognition, relationships, and independent learning."}, {"id": "032bd0b0-0080-4fba-83fe-082b17807806", "type": "subtopic", "title": "Culturally sustaining pedagogy", "children": [{"id": "ff72b3a8-0ab9-4a1b-a64e-93e604920b94", "type": "concept", "title": "Language and culture as living resources"}, {"id": "6dcdcffe-432c-4f1b-ad0b-93dd75fd07b6", "type": "concept", "title": "Youth culture and community knowledge"}, {"id": "7b56f2ba-d9a3-47ba-81e6-5b83a3b8d65a", "type": "concept", "title": "Avoiding assimilationist inclusion"}], "description": "Students learn to sustain rather than replace students' cultural and linguistic practices."}]}, {"id": "b920a68d-568b-48b6-b6c8-2e57defb48a0", "type": "topic", "title": "Anti-Bias Curriculum, Diverse Texts, and Critical Media Literacy", "description": "Curriculum teaches students whose knowledge counts. This unit prepares educators to evaluate materials, diversify texts, address bias, and build critical literacy without reducing culture to celebration.", "children": [{"id": "cff28ded-d1cd-4c60-be75-9210bd8094db", "type": "subtopic", "title": "Representation and curriculum audit", "children": [{"id": "382516c2-7c47-491a-b274-7f7b33120783", "type": "concept", "title": "Mirrors, windows, and sliding glass doors"}, {"id": "f14e7ab8-c850-4ccd-906c-c270ad72daab", "type": "concept", "title": "Tokenism and stereotypes"}, {"id": "02f1518f-c30a-48d7-ad22-79afd14c142c", "type": "concept", "title": "Curriculum mapping for representation and power"}], "description": "Students learn to examine whose stories, expertise, and perspectives appear in curriculum."}, {"id": "dfe9f5e5-e1c2-44f0-8abc-19094d373d5c", "type": "subtopic", "title": "Counter-narratives and people's history", "children": [{"id": "1e5d1ade-e2d2-41e0-bec7-dc72021ea06e", "type": "concept", "title": "Primary sources and local histories"}, {"id": "1cd186a1-6520-4eef-bd08-8b625ced2401", "type": "concept", "title": "Multiple perspectives and contested narratives"}, {"id": "f5d185e2-57c7-4fe3-b798-14fe4b4a56a2", "type": "concept", "title": "Student inquiry into justice and change"}], "description": "Students learn how alternative sources deepen historical and civic understanding."}, {"id": "f8a30413-4033-435f-9d1c-4d6d1bd635ba", "type": "subtopic", "title": "Critical media and information literacy", "children": [{"id": "88badbc2-b7f6-46d1-8ba8-9c36a33ed3e8", "type": "concept", "title": "Source evaluation and misinformation"}, {"id": "adfb3fba-d6b9-490a-96da-9c63282db2c8", "type": "concept", "title": "Visual and digital representation"}, {"id": "4fa99979-c862-4edf-8d10-8b751561a27c", "type": "concept", "title": "Bias, framing, and civic dialogue"}], "description": "Students learn to help students evaluate media, algorithms, and public discourse."}]}, {"id": "1037f87f-e2dc-482d-837d-ddaad2e92987", "type": "topic", "title": "Inclusive Classroom Climate, Restorative Practice, and Belonging", "description": "Equity lives in daily classroom routines. This unit focuses on relationship-centered practice, community building, discipline equity, and restorative responses that maintain dignity and accountability.", "children": [{"id": "32659419-f204-4db6-ac6c-09fe72c1db8d", "type": "subtopic", "title": "Belonging and classroom culture", "children": [{"id": "022fe62b-76d9-40dc-aad8-e133837f805e", "type": "concept", "title": "Community agreements and norms"}, {"id": "4d651bed-c896-4385-a43b-6c0642658598", "type": "concept", "title": "Student voice and co-creation"}, {"id": "a99576af-3c84-4d30-83bb-c9856bbea89d", "type": "concept", "title": "Belonging surveys and climate checks"}], "description": "Students learn to design routines that communicate safety, respect, and high expectations."}, {"id": "2f50759c-ca59-4483-8eb1-1278ba1931d6", "type": "subtopic", "title": "Restorative and culturally affirming practices", "children": [{"id": "d92bd1fe-4fc1-48d4-8b18-a87e48d13179", "type": "concept", "title": "Restorative circles and conferences"}, {"id": "078b55a0-84ae-401a-b3e7-d9749ff431fc", "type": "concept", "title": "Accountability without humiliation"}, {"id": "50f46448-fad2-4f0e-892a-8fe7171a80e2", "type": "concept", "title": "Culturally responsive classroom management"}], "description": "Students learn alternatives to exclusionary discipline that repair harm and sustain community."}, {"id": "8e38fc71-d994-4e83-91c5-9613d3a5d73a", "type": "subtopic", "title": "Trauma-informed and healing-centered practice", "children": [{"id": "95904e57-aeaf-4d77-9d9c-39fc71dd2928", "type": "concept", "title": "Predictability, choice, and regulation"}, {"id": "c6e82326-0b89-4dfa-837b-141f680371b1", "type": "concept", "title": "Avoiding pathologizing students"}, {"id": "55527c17-93fe-4456-829b-cb89b7333860", "type": "concept", "title": "Referral, boundaries, and educator care"}], "description": "Students learn how stress, trauma, and resilience intersect with identity and schooling."}]}, {"id": "296dd6f7-c566-4c5b-b950-a28f47c09359", "type": "topic", "title": "Family, Community, and Participatory Partnerships", "description": "Families and communities are not peripheral to learning. This unit prepares educators to build reciprocal partnerships that respect family expertise and share power.", "children": [{"id": "b86f0dc3-06b3-4d90-bd93-257321dd02a1", "type": "subtopic", "title": "Family engagement as partnership", "children": [{"id": "188e56db-ed07-4d9d-b6a2-a4b46d61c335", "type": "concept", "title": "Two-way communication"}, {"id": "66ebb1f4-d984-4621-b68a-27800ac22fbc", "type": "concept", "title": "Strengths-based family narratives"}, {"id": "ec37586b-8185-4ad4-af74-4e40557e3bd3", "type": "concept", "title": "Conferences, home visits, and trust building"}], "description": "Students learn to move beyond compliance-oriented communication toward authentic relationship."}, {"id": "c62785d4-4965-4451-85ee-93f1e11d0dee", "type": "subtopic", "title": "Language access and cultural responsiveness", "children": [{"id": "55f347f9-394e-4b40-a5b2-12afbff7650a", "type": "concept", "title": "Interpretation and translation"}, {"id": "1d03c1af-277a-4352-9b39-333a9cad1a22", "type": "concept", "title": "Avoiding child-as-interpreter practices"}, {"id": "dbf7363e-f769-4508-89af-a532cf197643", "type": "concept", "title": "Culturally responsive meeting design"}], "description": "Students learn to make school communication accessible and respectful."}, {"id": "f347c997-15a1-4153-8236-5fd49f38647c", "type": "subtopic", "title": "Community-based and participatory education", "children": [{"id": "66c7dfe1-19ee-4c9d-8951-ca2cb50ee1d1", "type": "concept", "title": "Community walks and asset mapping"}, {"id": "2441be02-da30-435c-a8a4-f4ab04ee653c", "type": "concept", "title": "Co-designed projects"}, {"id": "0f7da86e-e4b9-497e-be3c-6f90bf9fcfa6", "type": "concept", "title": "Youth and family voice in decision-making"}], "description": "Students learn to connect curriculum and improvement work to community priorities."}]}, {"id": "1766a90e-bc35-4998-b902-027653798f1c", "type": "topic", "title": "Civil Rights, Policy, Equity Data, and School Systems", "description": "Equity-centered educators need systems literacy. This unit introduces civil-rights obligations, data sources, and policy tools for identifying and addressing inequity beyond individual classrooms.", "children": [{"id": "4b421ffc-5f2c-428a-9ef2-8c6eaed7f6f4", "type": "subtopic", "title": "Civil rights and legal context", "children": [{"id": "98c05a50-a2d1-4c3d-b07c-ed086becc2dd", "type": "concept", "title": "Title VI, Title IX, Section 504, ADA, and language access"}, {"id": "91fe66e5-5960-4ee1-99c9-69cab42d5a09", "type": "concept", "title": "Office for Civil Rights roles"}, {"id": "fc6ec602-122f-4c59-a9c9-5c43c8c2794d", "type": "concept", "title": "Nondiscrimination, harassment, and equal access"}], "description": "Students learn the basic federal protections that shape school responsibilities."}, {"id": "8c139c72-f9c4-4878-8697-f2fe52e2f92f", "type": "subtopic", "title": "Equity data and disproportionality", "children": [{"id": "f673b475-fbb7-4019-bb6a-a9349673546c", "type": "concept", "title": "Civil Rights Data Collection"}, {"id": "2c32086c-ce83-4417-8337-aa7e09925201", "type": "concept", "title": "Discipline, course access, special education, and advanced opportunities"}, {"id": "17f4c84e-739b-4f4c-9f4c-2864fb9898e2", "type": "concept", "title": "Disaggregation, intersectionality, and small-number caution"}], "description": "Students learn to use data to ask better questions, not to label students or communities."}, {"id": "927ef84d-1da4-469c-a348-f0f6fcffe745", "type": "subtopic", "title": "Equity audits and improvement planning", "children": [{"id": "de18290f-b39b-4caa-8a85-c6df1dd08e4f", "type": "concept", "title": "Equity indicators and root-cause analysis"}, {"id": "aefa98cc-8b68-458d-9e31-401843a1fb48", "type": "concept", "title": "Stakeholder engagement"}, {"id": "b535a59a-f422-49de-9d0d-545a052d7e9e", "type": "concept", "title": "Monitoring outcomes and unintended consequences"}], "description": "Students learn how schools turn evidence into action."}]}, {"id": "c0138c08-69a2-4c96-9103-8ad6ebde7e64", "type": "topic", "title": "Teacher Leadership, Resistance, and Sustaining Equity Work", "description": "The capstone unit prepares students to sustain equity work as reflective professionals. Students learn to navigate resistance, build coalitions, measure progress, and keep students at the center.", "children": [{"id": "fdf71003-f4b7-438b-80d4-5a03143adc76", "type": "subtopic", "title": "Teacher leadership and coalition-building", "children": [{"id": "94022179-66a0-4767-81b8-c8c693bb7507", "type": "concept", "title": "Professional learning communities"}, {"id": "f7f0991b-93f3-41b1-afc6-9a5662aec532", "type": "concept", "title": "Coaching and peer inquiry"}, {"id": "0efa7ede-b0a1-4f16-b465-4e3298fc4b15", "type": "concept", "title": "Distributed leadership and shared responsibility"}], "description": "Students learn how classroom educators influence teams, curriculum, policy, and culture."}, {"id": "79b6f506-2d8f-43d3-9625-6b8f83c156f3", "type": "subtopic", "title": "Navigating conflict and resistance", "children": [{"id": "1f9a5651-12d4-41ce-aa92-02293ab549a6", "type": "concept", "title": "Facilitation across difference"}, {"id": "5867f47c-8059-4c4f-9e3c-43a8b543abc0", "type": "concept", "title": "Common resistance patterns"}, {"id": "61a9dce7-c0c8-44d2-a0b6-9e651b86822e", "type": "concept", "title": "Ethical boundaries and professional communication"}], "description": "Students learn to respond to disagreement with clarity, evidence, humility, and courage."}, {"id": "46b23c99-05ab-4b51-92c0-506d2995e634", "type": "subtopic", "title": "Sustaining practice and accountability", "children": [{"id": "beb6c0bb-6a99-4754-98d2-ec60cae956b9", "type": "concept", "title": "Equity-centered teaching artifacts"}, {"id": "61566e27-f5a7-4af