  ('032c443c-0f37-4c31-a043-515b95e1a461', 'c9d0e1f2-3a4b-4c76-9d56-6f7a8b9c0d66', '251a6383-2fbc-4398-9d79-dfa7c43e53be', 'concept'::public.curated_course_node_type, 'Medical, social, and justice models of disability', null, 0),
