  ('8621a49b-0c7f-40c6-8efc-f0945e09a63e', 'c9d0e1f2-3a4b-4c76-9d56-6f7a8b9c0d66', '251a6383-2fbc-4398-9d79-dfa7c43e53be', 'concept'::public.curated_course_node_type, 'Disability culture and student agency', null, 2),
  ('148deb3a-cd6a-473c-b336-0023a8ba7514', 'c9d0e1f2-3a4b-4c76-9d56-6f7a8b9c0d66', 'a54200b4-65cd-4009-bbeb-5f2e896b2893', 'subtopic'::public.curated_course_node_type, 'Universal Design for Learning', 'Students apply UDL as proactive design rather than individual remediation.', 1),
  ('00eced8d-9745-416c-827a-860469e746da', 'c9d0e1f2-3a4b-4c76-9d56-6f7a8b9c0d66', '148deb3a-cd6a-473c-b336-0023a8ba7514', 'concept'::public.curated_course_node_type, 'Multiple means of engagement', null, 0),
